// ─── File: src/main/java/com/bank/statement/service/AccountStatementService.java ───
package com.bank.statement.service;

import com.bank.statement.dto.AccountStatementDTO;
import com.bank.statement.dto.AccountStatementDTO.TradeItem;
import com.bank.statement.model.Account;
import com.bank.statement.repository.AccountRepository;
import lombok.RequiredArgsConstructor;
import lombok.extern.slf4j.Slf4j;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import java.util.List;

@Service
@RequiredArgsConstructor
@Slf4j
public class AccountStatementService {

    private final AccountRepository accountRepo;

    // ═══ readOnly=true: skip dirty checking + hint DB for read replica ═══
    @Transactional(readOnly = true)
    public AccountStatementDTO getStatement(String accountId) {
        // JOIN FETCH loads account + trades in ONE query (inside transaction)
        Account account = accountRepo.findWithTrades(accountId)
            .orElseThrow(() -> new IllegalArgumentException("Account not found: " + accountId));

        // Map to DTO INSIDE the transaction (session still open)
        List<TradeItem> tradeItems = account.getTrades().stream()
            .map(t -> new TradeItem(t.getTradeId(), t.getSymbol(), t.getAmount()))
            .toList();

        log.info("[readOnly=true] Loaded {} trades for {} — NO dirty checking, NO snapshots",
            tradeItems.size(), accountId);

        // Return DTO — session closes after this method returns
        // Controller receives a DTO with no lazy proxies — safe to serialize
        return new AccountStatementDTO(
            account.getAccountId(), account.getHolderName(), account.getBalance(),
            tradeItems, "JOIN FETCH + DTO + readOnly=true");
    }

    // ═══ WRONG: return entity directly (OSIV would mask the problem) ═══
    @Transactional(readOnly = true)
    public Account getAccountEntity(String accountId) {
        return accountRepo.findById(accountId)
            .orElseThrow(() -> new IllegalArgumentException("Not found: " + accountId));
        // WITHOUT JOIN FETCH: trades are LAZY
        // If OSIV=false: accessing trades in controller → LazyInitializationException!
        // If OSIV=true: trades load lazily during JSON serialization → N+1 + long connection hold
    }
}
```

