@RequiredArgsConstructor
public class StatementController {

    private final AccountStatementService service;

    // (Recommended) CORRECT: returns DTO — no lazy proxy issues
    @GetMapping("/{accountId}")
    public AccountStatementDTO getStatement(@PathVariable String accountId) {
        return service.getStatement(accountId);
    }
}
