package com.bank.statement.service;

import org.junit.jupiter.api.Test;
import static org.assertj.core.api.Assertions.*;

class ReadOnlyAndOsivTest {

    @Test
    void readOnlySkipsDirtyChecking() {
        // @Transactional(readOnly=true):
        // 1. Hibernate does NOT take load-time snapshots
        // 2. At flush: no comparison runs (nothing to compare)
        // 3. If you modify an entity: change is SILENTLY IGNORED (no UPDATE generated)
        // 4. Some DBs: lighter locking, read replica routing

        // This is a conceptual test — verifying understanding
        assertThat(true).isTrue();
    }

    @Test
    void dirtyCheckingComparesAllFields() {
        // For each managed entity, Hibernate stores snapshot at load time:
        // snapshot = {accountId="SAV2001", balance=125000, version=1}
        // At flush: compare current state vs snapshot field-by-field
        // If ANY field differs → generate UPDATE SQL
        // 1000 entities × 20 fields = 20,000 comparisons per flush!

        int entities = 1000;
        int fieldsPerEntity = 20;
        int comparisons = entities * fieldsPerEntity;
        assertThat(comparisons).isEqualTo(20000);
    }

    @Test
    void osivHoldsConnectionDuringEntireRequest() {
        // OSIV enabled: Session open from controller entry → JSON serialization → response sent
        // Request duration with lazy loads: 50ms service + 500ms serialization = 550ms connection hold
        // 10 connections, 200 concurrent users: 190 WAITING for connection!
        // HikariCP timeout: "Connection not available, request timed out after 30000ms"

        int poolSize = 10;
        int concurrentUsers = 200;
        int waiting = concurrentUsers - poolSize;
        assertThat(waiting).isEqualTo(190);
    }

    @Test
    void correctArchitecture() {
        // 1. @Transactional(readOnly=true) in service
        // 2. JOIN FETCH loads all needed data in one query
        // 3. Map entity → DTO inside the transaction
        // 4. Return DTO to controller (no lazy proxies)
        // 5. Session closes immediately after service method returns
        // 6. Connection returned to pool FAST
        // 7. OSIV disabled — no surprise lazy loads

        // This is the correct pattern for production Spring Boot APIs.
        assertThat(true).isTrue();
    }
}
```
